module Snapshot : sig
  type t

  module Id : sig
    type t

    val of_string : string -> (t, Error.t) result
    val to_string : t -> string
    val equal : t -> t -> bool
  end

  module Input : sig
    type session = { id : Session.Id.t; name : string; attached : int }

    type window = {
      id : Window.Id.t;
      name : string;
      width : int;
      height : int;
      layout : string;
    }

    type window_link = {
      session_id : Session.Id.t;
      window_id : Window.Id.t;
      index : int;
      is_current : bool;
    }

    type pane = {
      id : Pane.Id.t;
      window_id : Window.Id.t;
      index : int;
      active : bool;
      dead : bool;
      title : string;
      current_command : string;
      current_path : string;
      pid : int option;
      width : int;
      height : int;
      left : int;
      top : int;
    }

    type client = {
      name : string;
      session_id : Session.Id.t option;
      pid : int;
      width : int;
      height : int option;
      control_mode : bool;
    }
  end

  val create :
    source:Source.t ->
    id:Id.t ->
    started_at_ns:int64 ->
    finished_at_ns:int64 ->
    sessions:Input.session list ->
    windows:Input.window list ->
    window_links:Input.window_link list ->
    panes:Input.pane list ->
    clients:Input.client list ->
    (t, Error.t) result
  (** Validate and materialize a complete captured graph without I/O. Equal
      duplicate global rows collapse in first-occurrence order; conflicting rows
      and dangling references return {!Error.Capture_raced}. Links at different
      indexes remain distinct, including within one session. At most 10,000
      input rows are admitted. Each session needs one current link and each
      window one active pane. Capture spans an interval, not an atomic instant.
      Input strings are bytes; no Unicode normalization is performed. *)

  val id : t -> Id.t
  val source : t -> Source.t
  val started_at_ns : t -> int64
  val finished_at_ns : t -> int64
  val sessions : t -> Session.t Iarray.t
  val windows : t -> Window.t Iarray.t
  val window_links : t -> Window_link.t Iarray.t
  val panes : t -> Pane.t Iarray.t

  val clients : t -> Client_observation.t Iarray.t
  (** Collections and their contents are immutable. They retain capture order,
      are replayable and remain readable after the acquiring client closes. *)

